/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-11: new module - read-only user directory (readOnlyUserDir): protected
 *   directories, the error read_only_user_dir and the effective settings
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Read-only user directory (Z-11).
 *
 * With `readOnlyUserDir: true` (or the CLI environment variable
 * `NODE_RED_READ_ONLY_USER_DIR`, R-18, R-33) the runtime does not write to the
 * user directory:
 *  - the features that need to write are disabled (`applySettings`): palette
 *    install/upload/update, auto-install of missing modules, modules of the
 *    function node, Projects
 *  - the file storage skips the writes of settings and sessions (like
 *    `readOnly`) and rejects deployments and library entries with 400
 *    `read_only_user_dir` (R-18) - also for an absolute `flowFile` outside the
 *    user directory (R-40)
 *  - a `localfilesystem` context store inside a protected directory fails the
 *    start (R-18, D-15)
 *
 * Protected directories: `userDir`; when it is not set, the directories the
 * runtime falls back to: `NODE_RED_HOME`, the current directory and
 * `~/.node-red`.
 * @module
 */

const path = require("path");
const { log } = require("@node-red/util");

/**
 * @param {Object} settings
 * @return {boolean} whether `readOnlyUserDir: true` is set
 */
function isEnabled(settings) {
    return !!settings && settings.readOnlyUserDir === true;
}

/**
 * @param {Object} settings
 * @return {Array<string>} the protected directories (resolved)
 */
function protectedDirs(settings) {
    const dirs = [];
    if (settings && settings.userDir) {
        dirs.push(path.resolve(settings.userDir));
    } else {
        if (process.env.NODE_RED_HOME) {
            dirs.push(path.resolve(process.env.NODE_RED_HOME));
        }
        dirs.push(process.cwd());
        const home = process.env.HOME || process.env.USERPROFILE || process.env.HOMEPATH;
        if (home) {
            dirs.push(path.resolve(home, ".node-red"));
        }
    }
    return dirs.filter(function(d, i) { return dirs.indexOf(d) === i });
}

/**
 * @param {string} p - a path
 * @param {Object} settings
 * @return {boolean} whether `p` is a protected directory or inside one
 */
function isProtected(p, settings) {
    const target = path.resolve(p);
    return protectedDirs(settings).some(function(dir) {
        return target === dir || target.startsWith(dir.endsWith(path.sep) ? dir : dir + path.sep);
    });
}

/**
 * @param {string} [feature] - what needs to write (for the message)
 * @return {Error} 400 `read_only_user_dir`
 */
function error(feature) {
    const err = new Error(log._("readonly-userdir.write-rejected", { feature: feature || "" }));
    err.code = "read_only_user_dir";
    err.status = 400;
    return err;
}

/**
 * Throws `read_only_user_dir` when the setting is enabled and `p` is protected.
 * @param {string} p
 * @param {Object} settings
 * @param {string} [feature]
 */
function assertWritable(p, settings, feature) {
    if (isEnabled(settings) && isProtected(p, settings)) {
        throw error(feature);
    }
}

function ensureObject(parent, key) {
    if (!parent[key] || typeof parent[key] !== "object") {
        parent[key] = {};
    }
    return parent[key];
}

/**
 * Disables the features that write to the user directory, in the settings
 * object given to the runtime (before the runtime settings are initialised).
 * Flags are only narrowed: a feature disabled elsewhere stays disabled.
 * @param {Object} settings - the user settings object
 * @return {{overridden: Array<string>}} the settings that were set to `true`
 *     and are overridden (logged as warnings at start)
 */
function applySettings(settings) {
    const overridden = [];
    if (!isEnabled(settings)) {
        return { overridden: overridden };
    }
    const externalModules = ensureObject(settings, "externalModules");
    const palette = ensureObject(externalModules, "palette");
    const modules = ensureObject(externalModules, "modules");
    const set = function(obj, key, name) {
        if (obj[key] === true) {
            overridden.push(name);
        }
        obj[key] = false;
    };
    set(externalModules, "autoInstall", "externalModules.autoInstall");
    set(palette, "allowInstall", "externalModules.palette.allowInstall");
    set(palette, "allowUpload", "externalModules.palette.allowUpload");
    set(palette, "allowUpdate", "externalModules.palette.allowUpdate");
    set(modules, "allowInstall", "externalModules.modules.allowInstall");
    // Projects are disabled unless editorTheme.projects.enabled is true: only an
    // existing projects setting is changed (no editorTheme is added)
    if (settings.editorTheme && settings.editorTheme.projects && typeof settings.editorTheme.projects === "object") {
        set(settings.editorTheme.projects, "enabled", "editorTheme.projects.enabled");
    }
    if (settings.autoInstallModules) {
        // Deprecated setting - superseded by externalModules.autoInstall: false
        overridden.push("autoInstallModules");
    }
    return { overridden: overridden };
}

/**
 * Logs the block of disabled features at start, and a warning for every
 * overridden setting.
 * @param {Array<string>} overridden
 */
function logStartup(overridden) {
    log.info(log._("readonly-userdir.enabled"));
    (overridden || []).forEach(function(name) {
        log.warn(log._("readonly-userdir.setting-overridden", { setting: name }));
    });
}

module.exports = {
    isEnabled,
    protectedDirs,
    isProtected,
    error,
    assertWritable,
    applySettings,
    logStartup
};
